package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity@Table(name="spms_rating_item_result",uniqueConstraints=@UniqueConstraint(name="uk_spms_rating_item_result",columnNames={"agency_id","assessment_id","source_item_id"}))public class PerformanceRatingItemResult extends RspAuditedEntity{@Column(name="assessment_id",nullable=false,length=36)private String assessmentId;@Column(name="source_item_id",nullable=false,length=36)private String sourceItemId;@Column(name="raw_score",nullable=false,precision=19,scale=8)private BigDecimal rawScore;@Column(name="rounded_score",nullable=false,precision=19,scale=6)private BigDecimal roundedScore;@Column(name="weighted_contribution",nullable=false,precision=19,scale=8)private BigDecimal weightedContribution;protected PerformanceRatingItemResult(){}public PerformanceRatingItemResult(String a,String assessment,String source,BigDecimal raw,BigDecimal rounded,BigDecimal contribution){super(a);assessmentId=requiredText(assessment,"assessmentId");sourceItemId=requiredText(source,"sourceItemId");rawScore=raw;roundedScore=rounded;weightedContribution=contribution;}public String getAssessmentId(){return assessmentId;}public String getSourceItemId(){return sourceItemId;}public BigDecimal getRawScore(){return rawScore;}public BigDecimal getRoundedScore(){return roundedScore;}public BigDecimal getWeightedContribution(){return weightedContribution;}}
